package com.moodcanvas.dao;
import com.moodcanvas.model.JournalEntry;import com.moodcanvas.util.DBConnection;import java.sql.*;import java.util.*;
public class JournalDAO {public List<JournalEntry> getJournalByUser(int u)throws SQLException{List<JournalEntry>a=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM journal_entries WHERE userID=? ORDER BY savedAt DESC")){p.setInt(1,u);try(ResultSet r=p.executeQuery()){while(r.next())a.add(new JournalEntry(r.getInt("journalID"),r.getString("artworkID"),r.getString("title"),r.getString("artist"),r.getString("imageURL"),r.getString("museum"),r.getTimestamp("savedAt")));}}return a;}public void saveEntry(int u,String id,String t,String a,String i,String m)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO journal_entries(userID,artworkID,title,artist,imageURL,museum) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE title=VALUES(title),artist=VALUES(artist),imageURL=VALUES(imageURL),museum=VALUES(museum)")){p.setInt(1,u);p.setString(2,id);p.setString(3,t);p.setString(4,a);p.setString(5,i);p.setString(6,m);p.executeUpdate();}}public boolean remove(int u,int id)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM journal_entries WHERE journalID=? AND userID=?")){p.setInt(1,id);p.setInt(2,u);return p.executeUpdate()>0;}}public int count()throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT COUNT(*) FROM journal_entries");ResultSet r=p.executeQuery()){r.next();return r.getInt(1);}}}
